#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    MainSpawnTypeSceneChancesV29, MAIN_SPAWN_TYPE_SCENE_CHANCES_V29
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Emit main-spawn-type-chances.generated.ts from v29 Unity asset extract.
 *
 *   node scripts/build-main-spawn-chances.mjs
 *
 * Source: packages/platform/src/game-data/v29.0/main-spawn-type-chances-native.json
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const REPO_ROOT = path.resolve(PACKAGE_ROOT, '..', '..')
const SRC_JSON = path.join(
  REPO_ROOT,
  'packages',
  'platform',
  'src',
  'game-data',
  'v29.0',
  'main-spawn-type-chances-native.json',
)
const OUT = path.join(PACKAGE_ROOT, 'src', 'data', 'generated', 'main-spawn-type-chances.generated.ts')

const payload = fs.existsSync(SRC_JSON)
  ? JSON.parse(fs.readFileSync(SRC_JSON, 'utf8'))
  : { primary: null, hits: [] }

const primary = payload.primary ?? null

const body = `/** @generated node scripts/build-main-spawn-chances.mjs — do not edit */
export type MainSpawnTypeSceneChancesV29 = {
  chanceNormalEnemy: number
  chanceFastEnemy: number
  chanceTankEnemy: number
  chanceRangedEnemy: number
  chanceProtectorEnemy: number
}

/** Scene-serialized Main.chance*Enemy ints from APK scan; null until extract populates primary. */
export const MAIN_SPAWN_TYPE_SCENE_CHANCES_V29: MainSpawnTypeSceneChancesV29 | null = ${
  primary
    ? JSON.stringify(
        {
          chanceNormalEnemy: primary.chanceNormalEnemy ?? 0,
          chanceFastEnemy: primary.chanceFastEnemy ?? 0,
          chanceTankEnemy: primary.chanceTankEnemy ?? 0,
          chanceRangedEnemy: primary.chanceRangedEnemy ?? 0,
          chanceProtectorEnemy: primary.chanceProtectorEnemy ?? 0,
        },
        null,
        2,
      )
    : 'null'
}
`

fs.mkdirSync(path.dirname(OUT), { recursive: true })
fs.writeFileSync(OUT, body)
console.log(`Wrote ${OUT} (primary=${primary ? 'yes' : 'null'})`)
